contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _lockTime, uint256 _amount) internal {
        _amount = bound(_amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _amount);
        vm.assume(_amount > 0);
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        try c.Put{value: _amount}(_lockTime) {} catch { return; }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        assertTrue(afterBalance >= beforeBalance && afterUnlock >= beforeUnlock);
    }

    function testFuzz_run(uint256 _lockTime, uint256 _amount) public {
        _run(_lockTime, _amount);
    }

    receive() external payable {}
}
